import { writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { getPersonas, getRoles } from '../lib/catalog';

/**
 * Writes content/INDEX.md: one line per persona with its path, tone, platforms
 * and placeholders. Agents (and ~/.claude/CLAUDE.md's persona-agents rule)
 * grep this file to pick a system prompt for a role-shaped task.
 * Run: pnpm build:index   (also run by check:content)
 */
const roles = await getRoles();
const personas = await getPersonas();

const lines: string[] = [
  '# Persona library index',
  '',
  'Generated by `pnpm build:index`; do not edit. One line per persona: `role/slug` · name · tone · platforms · placeholders. The system prompt is the markdown body of the file (after the frontmatter); fill `{{KEYS}}` before use.',
  '',
];

for (const role of roles) {
  const mine = personas.filter((p) => p.roleSlug === role.slug);
  if (mine.length === 0) continue;
  lines.push(`## ${role.name} (${role.department}) — \`${role.slug}\``, '', role.summary, '');
  for (const p of mine) {
    const path = `content/personas/${p.roleSlug}/${p.slug}.md`;
    const keys = p.placeholders.map((ph) => ph.key).join(', ');
    lines.push(`- \`${path}\` · **${p.name}**${p.isDefault ? ' (default)' : ''} · ${p.tone} · ${p.platforms.join('/')} · ${p.tagline} · keys: ${keys}`);
  }
  lines.push('');
}

const out = join(process.cwd(), 'content', 'INDEX.md');
await writeFile(out, lines.join('\n'));
console.log(`wrote ${out}: ${roles.length} roles, ${personas.length} personas`);
